// ──────────────────────────── /api/attribution ────────────────────────────

/** One variant's measured row inside an attribution cell. */
export interface AttributionRow {
  variant: string | null;
  method: MethodKey;
  seeds: number;
  aubqc: number;
  aubqc_se: number;
  aubqc_per_seed: number[];
  rho: number;
  rho_n: number;
  rho_per_seed: number[];
}

/** One `production - variant` paired delta on AUBQC and on ρ. */
export interface AttributionDelta {
  aubqc: { n: number; mean_diff: number; se: number; p_value: number; seeds_won: number };
  rho: { n: number; mean_diff: number; se: number; p_value: number; seeds_won: number };
}

/** One target × coverage cell of the ablation ledger. */
export interface AttributionCell {
  cell: string;
  protocol: CampaignProtocolBlock;
  seeds: number;
  /** The production row is keyed `"None"` in JSON — it is the unablated variant. */
  rows: Record<string, AttributionRow>;
  production_minus: Record<string, AttributionDelta>;
  _provenance: {
    production_row_source: string;
    mechanism_rows_source: string;
    mechanism_rows_caveat: string;
  };
}

/** `GET /api/attribution` — the negative-control ledger. */
export interface AttributionPayload {
  available: boolean;
  seeds: number;
  cells: AttributionCell[];
  path?: string;
  detail?: string;
}
